-- makro-liquor-wonderboom-annlin-west (owner)
UPDATE businesses SET description = 'Makro Liquor Wonderboom is a dedicated liquor outlet operating alongside the main Makro store at 270 Lavender Road, Annlin West, Pretoria. As part of the Makro liquor network, it stocks a broad range of beer, wine, spirits and other alcoholic drinks, with Makro''s bulk-retail format suiting customers who want to compare a wide selection and buy multiple bottles, cases or packs rather than relying on a small neighbourhood liquor store. The branch serves households buying for everyday use, as well as customers stocking up for parties, functions and other events, and it suits businesses or individuals needing larger beverage quantities. It is listed separately from the main Wonderboom Makro store, with its own trading hours: Monday to Friday from 8:30am to 6pm, Saturday from 8am to 5pm and Sunday from 9am to 3:30pm, slightly shorter than the main store on Sundays.', description_enriched_at = datetime('now') WHERE slug = 'makro-liquor-wonderboom-annlin-west' AND description = 'Makro Liquor Wonderboom is a liquor store in Annlin West, Pretoria.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
